package glitch

import data.glitch_lib

integrity_keywords := {"integrity", "checksum", "verification", "hmac", "hash", "signature", "signing", "unsigned", "mac", "sign", "checksum_algorithm", "use_checksum", "verify_integrity", "message_authentication", "hash_algorithm", "enable_integrity", "integrity_protection", "data_integrity", "require_signing", "checksum_type", "allow_unsigned", "skip_integrity_check", "disable_checksum", "enforce_integrity"}

disablement_values := {"false", "disabled", "none", "no", "0", "off", "disabled"}

is_disabled_pattern(value) {
    value.ir_type == "Boolean"
    not value.value
} else {
    value.ir_type == "String"
    lower_val := lower(value.value)
    disablement_values[lower_val]
} else {
    value.ir_type == "Integer"
    value.value == 0
}

has_integrity_keyword(name) {
    lower_name := lower(name)
    keyword := integrity_keywords[_]
    contains(lower_name, keyword)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    has_integrity_keyword(attr.name)
    is_disabled_pattern(attr.value)

    not glitch_lib.traverse_var(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing or disabled integrity check - Ensure integrity verification mechanisms are enabled for data in transit or at rest. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    has_integrity_keyword(var.name)
    is_disabled_pattern(var.value)

    not glitch_lib.traverse_var(var.value)

    result := {
        "type": "sec_no_int_check",
        "element": var,
        "path": parent.path,
        "description": "Missing or disabled integrity check - Ensure integrity verification mechanisms are enabled for data in transit or at rest. (CWE-353)"
    }
}

